import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"LINE Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/line.md","filePath":"integrations/channels/line.md","lastUpdated":1785920317000}'),s={name:"integrations/channels/line.md"};function i(r,e,l,h,g,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="line-channel-configuration" tabindex="-1">LINE Channel Configuration <a class="header-anchor" href="#line-channel-configuration" aria-label="Permalink to &quot;LINE Channel Configuration&quot;">​</a></h1><p>Connecting your Memoh Bot to LINE lets it chat with users through a LINE Official Account in one-on-one conversations.</p><h2 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h2><p>LINE delivers messages to Memoh through a <strong>webhook</strong>, so your Memoh deployment must expose a public HTTPS endpoint:</p><ul><li>Set <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> to your public HTTPS origin (no path, port, or private address), or</li><li>Enable the Cloudflare Quick Tunnel profile in the server deploy stack, and Memoh will obtain a public URL automatically.</li></ul><p>Outbound images are also fetched by LINE&#39;s servers from your deployment, so the same public HTTPS requirement applies to sending pictures.</p><h2 id="step-1-create-a-line-messaging-api-channel" tabindex="-1">Step 1: Create a LINE Messaging API Channel <a class="header-anchor" href="#step-1-create-a-line-messaging-api-channel" aria-label="Permalink to &quot;Step 1: Create a LINE Messaging API Channel&quot;">​</a></h2><ol><li>Go to the <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>.</li><li>Create a provider (or pick an existing one), then create a <strong>Messaging API</strong> channel. This links the channel to a LINE Official Account.</li><li>In <strong>Basic settings</strong>, copy the <strong>Channel secret</strong>.</li><li>In the <strong>Messaging API</strong> tab, issue and copy a <strong>Channel access token</strong> (long-lived).</li></ol><blockquote><p>Official Guide: <a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">LINE Messaging API - Getting Started</a></p></blockquote><h2 id="step-2-configure-memoh" tabindex="-1">Step 2: Configure Memoh <a class="header-anchor" href="#step-2-configure-memoh" aria-label="Permalink to &quot;Step 2: Configure Memoh&quot;">​</a></h2><ol><li>Go to your Bot&#39;s <strong>Platforms</strong> tab in the Memoh Web UI.</li><li>Click <strong>Add Channel</strong> and select <strong>LINE</strong>.</li><li>Paste your <strong>Channel Secret</strong> and <strong>Channel Access Token</strong>.</li><li>Click <strong>Save</strong> (or <strong>Save and Enable</strong>). The webhook callback URL is generated only after the configuration is saved.</li></ol><h2 id="step-3-register-the-webhook" tabindex="-1">Step 3: Register the Webhook <a class="header-anchor" href="#step-3-register-the-webhook" aria-label="Permalink to &quot;Step 3: Register the Webhook&quot;">​</a></h2><p>After saving, the panel shows a read-only <strong>WebHook Callback URL</strong> in the form:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-public-base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>You have two ways to register it:</p><ul><li>Click <strong>Set in LINE</strong> — Memoh writes the webhook endpoint into your LINE channel directly through the Messaging API. Save any pending changes first, otherwise the button reports an error.</li><li>Or click <strong>Copy</strong> and paste the URL into <strong>Messaging API → Webhook URL</strong> in the LINE Developers Console manually.</li></ul><p>Then, in the LINE Developers Console, make sure <strong>Use webhook</strong> is enabled for the channel. If the panel warns that no public base URL is available, fix the <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> / tunnel setup first.</p><h2 id="features-supported" tabindex="-1">Features Supported <a class="header-anchor" href="#features-supported" aria-label="Permalink to &quot;Features Supported&quot;">​</a></h2><ul><li><strong>One-on-one chat</strong>: Users chat with the bot by adding the linked LINE Official Account as a friend.</li><li><strong>Inbound messages</strong>: Text, images, and files sent by the user. Images must be hosted by LINE itself (the normal case for photos sent from the app).</li><li><strong>Outbound messages</strong>: Text, plus PNG/JPEG images.</li><li><strong>Signature verification</strong>: Incoming webhooks are verified against your Channel Secret; events are deduplicated for 24 hours.</li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Private chats only.</strong> Group and multi-person room messages are ignored — inviting the bot into a LINE group has no effect.</li><li><strong>Inbound audio, video, stickers, and location messages are not processed.</strong></li><li>Outbound images must be publicly reachable over HTTPS and within LINE&#39;s size limits (10 MB original, 1 MB preview). Non-image attachments cannot be sent to LINE.</li><li>Replies are delivered through the LINE <strong>Push API</strong>, so they count against your LINE plan&#39;s push message quota.</li><li>Responses arrive as complete messages; LINE does not support incremental streaming output.</li><li>Long replies are split into multiple messages at LINE&#39;s 5000-character limit.</li></ul>',21)])])}const d=t(s,[["render",i]]);export{p as __pageData,d as default};
